ST.xhtml:p:
RTrigger1(CLK := bSustain1Home);
RTrigger2(CLK := bSustain2Home);
RTrigger3(CLK := bSustain3Home);
RTrigger7(CLK := bSustain7Home);
RTrigger8(CLK := bSustain8Home);
RTrigger9(CLK := bSustain9Home);

IF RTrigger1.Q THEN
    nSustain1HomeState := 1;
    g_bSustain1HomeDone := FALSE;
    bSustain1Home := FALSE;
END_IF;
IF RTrigger2.Q THEN
    nSustain2HomeState := 1;
    g_bSustain2HomeDone := FALSE;
    bSustain2Home := FALSE;
END_IF;
IF RTrigger3.Q THEN
    nSustain3HomeState := 1;
    g_bSustain3HomeDone := FALSE;
    bSustain3Home := FALSE;
END_IF;

IF RTrigger7.Q THEN
    nSustain7HomeState := 1;
    g_bSustain7HomeDone := FALSE;
    bSustain7Home := FALSE;
END_IF;
IF RTrigger8.Q THEN
    nSustain8HomeState := 1;
    g_bSustain8HomeDone := FALSE;
    bSustain8Home := FALSE;
END_IF;
IF RTrigger9.Q THEN
    nSustain9HomeState := 1;
    g_bSustain9HomeDone := FALSE;
    bSustain9Home := FALSE;
END_IF;

CASE nSustain1HomeState OF
  0:
    nSustain1HomeState := 0;
  1:
    g_Sustain1Home.Execute := TRUE;
    g_Sustain1Home.Position := dSustain1HomePosition;
    g_Sustain1Home.bCalibrationCam := g_bSusTain1HomeCal;
    g_Sustain1Home.DISTANCE := dSustain1HomeOffset;
    IF nSustain1HomeMode = 0 THEN
      g_Sustain1Home.HomingMode := 0;
    ELSIF nSustain1HomeMode = 1 THEN
      g_Sustain1Home.HomingMode := 5;
    ELSIF nSustain1HomeMode = 3 THEN
       (*只是去掉回零标志位*)
      g_Sustain1Home.HomingMode := 1;
    END_IF;
    IF g_Sustain1Home.Done THEN
      g_Sustain1Home.Execute := FALSE;
      nSustain1HomeState := 0;
      g_bSustain1HomeDone := TRUE;
    END_IF;

    IF g_bPlcPauseBuffer THEN
      nSustain1HomeState := 20;
    END_IF;
    IF g_Sustain1Home.CommandAborted OR g_Sustain1Home.Error THEN
      g_Sustain1Home.Execute := FALSE;
      nSustain1HomeState := 0;
    END_IF;
  20:
    g_Sustain1Home.Execute := FALSE;
    g_Sustain1Stop.Execute := TRUE;
    IF g_Sustain1Stop.Done AND g_bPlcStartBuffer THEN
      g_Sustain1Stop.Execute := FALSE;
      nSustain1HomeState := 1;
    END_IF;
    IF g_Sustain1Stop.CommandAborted OR g_Sustain1Stop.Error THEN
      g_Sustain1Stop.Execute := FALSE;
      nSustain1HomeState := 0;
    END_IF;
END_CASE;

