IF bChangeHomeMode THEN
  bChangeHomeMode := FALSE;
  nChangeHomeModeState := nChangeModeAxis;
END_IF;
CASE nChangeHomeModeState OF
  0:
    nChangeHomeModeState := 0;
  1:
    g_Sustain1Home.Execute := TRUE;
    IF nSustain1HomeMode = 0 THEN
      g_Sustain1Home.HomingMode := 0;
