      g_Sustain1Home.HomingMode := 5;
    ELSIF nSustain1HomeMode = 2 THEN
      g_Sustain1Home.HomingMode := 4;
    END_IF;
    g_Sustain1Home.Position := 0.0;
    g_Sustain1Home.DISTANCE := 0.0;
    IF g_Sustain1Home.Done THEN
      g_Sustain1Home.Execute := FALSE;
      nChangeHomeModeState := 0;
      g_bSustain1HomeDone := TRUE;
    END_IF;
    IF g_Sustain1Home.CommandAborted OR g_Sustain1Home.Error THEN
      g_Sustain1Home.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
   2:
    g_Sustain2Home.Execute := TRUE;
