(***界面上下发了去掉S1轴回零标志***)
IF g_bCleanS1Homed THEN
   g_Sustain1Home.HomingMode := 1;
   g_Sustain1Home.Execute := TRUE; 
   g_bSustain1HomeDone := FALSE; 
   IF g_Sustain1Home.DONE OR g_Sustain1Home.ERROR THEN 
    g_Sustain1Home.Execute := FALSE; 
    g_bCleanS1Homed := FALSE; 
   END_IF;
END_IF;
