(*伺服断电恢复基准点*)
Rtring_S1Recover(CLK := g_bRecoverS1DatumMark);
IF Rtring_S1Recover.Q THEN
  g_bRecoverS1DatumMark := FALSE;
  nRecoverS1DatumMarkState := 1;
END_IF;
CASE nRecoverS1DatumMarkState OF
  1:
   g_Sustain1Home.HomingMode := 4;
   g_Sustain1Home.Position :=g_dS1DatumMark; (*恢复基准点坐标差值*)
   g_Sustain1Home.Execute := TRUE;  
   IF  g_Sustain1Home.DONE OR g_Sustain1Home.ERROR THEN 
		g_bSustain1HomeDone := TRUE;
		g_Sustain1Home.Execute := FALSE; 
		nRecoverS1DatumMarkState := 0; 
   END_IF;
END_CASE;

