IF g_bPlcResetBuffer THEN
  nSustain1HomeState := 0;
  nSustain2HomeState := 0;
  nSustain3HomeState := 0;
  nSustain7HomeState := 0;
  nSustain8HomeState := 0;
  nSustain9HomeState := 0;
  nChangeHomeModeState := 0;
  g_Sustain1Stop.Execute := FALSE;
  g_Sustain1Home.Execute := FALSE;
  g_Sustain2Stop.Execute := FALSE;
  g_Sustain2Home.Execute := FALSE;
  g_Sustain3Stop.Execute := FALSE;
  g_Sustain3Home.Execute := FALSE;
  g_Sustain7Stop.Execute := FALSE;
  g_Sustain7Home.Execute := FALSE;
  g_Sustain8Stop.Execute := FALSE;
  g_Sustain8Home.Execute := FALSE;
  g_Sustain9Stop.Execute := FALSE;
  g_Sustain9Home.Execute := FALSE;

  g_bSustain1HomeDone := TRUE;
  g_bSustain2HomeDone := TRUE;
  g_bSustain3HomeDone := TRUE;
  g_bSustain7HomeDone := TRUE;
  g_bSustain8HomeDone := TRUE;
  g_bSustain9HomeDone := TRUE;

  g_bRecoverS1DatumMark := FALSE;
  g_bRecoverS2DatumMark := FALSE;
  g_bRecoverS3DatumMark := FALSE;
  g_bRecoverS4DatumMark := FALSE;
  g_bRecoverS5DatumMark := FALSE;
  g_bRecoverS6DatumMark := FALSE;

END_IF;
g_nS1HomeMode := nSustain1HomeMode;
g_nS2HomeMode := nSustain2HomeMode;
g_nS3HomeMode := nSustain3HomeMode;
g_nS4HomeMode := nSustain7HomeMode;
g_nS5HomeMode := nSustain8HomeMode;
g_nS6HomeMode := nSustain9HomeMode;
